#!/usr/bin/env node
/**
 * Generates the concrete 501 implementation of an NSwag-generated abstract
 * controller.
 *
 * NSwag's abstract controller style emits the routed base class and stops; the
 * class that ASP.NET Core actually discovers still has to exist. Writing that by
 * hand would put twelve hand-authored overrides of a generated signature into the
 * stub, and `AUTH-020` criterion 4 says generated files are never hand-edited.
 * The signatures transform mechanically, so this derives the subclass from them
 * instead — the whole stub stays generated, and the same command serves
 * `AUTH-021` and `AUTH-022` without repeating the work (ADR-0006, operational
 * finding 4).
 *
 * It reads only what NSwag wrote: the abstract signatures and the base class
 * name. It deliberately does NOT reproduce the routing attributes — those are
 * inherited from the base class, and copying them would be a second, divergable
 * source for the route table.
 *
 * Usage: node scripts/generate-stub-impl.mjs <generated-controller.cs> <output.cs>
 */
import { readFile, writeFile } from 'node:fs/promises';

const [input, output] = process.argv.slice(2);
if (!input || !output) {
  console.error('Usage: node scripts/generate-stub-impl.mjs <generated-controller.cs> <output.cs>');
  process.exit(1);
}

const source = await readFile(input, 'utf8');

const namespace = source.match(/^namespace\s+([\w.]+)/m)?.[1];
const baseClass = source.match(/^\s*public abstract class (\w+)\s*:/m)?.[1];
if (!namespace || !baseClass) {
  console.error(`${input}: FAILED — no namespace or abstract controller class found. Did NSwag run?`);
  process.exit(1);
}

// The subclass must end in "Controller" or ASP.NET Core will not discover it.
// NSwag names the base `<ClassName>ControllerBase`, so dropping the suffix yields
// exactly that.
const implClass = baseClass.replace(/Base$/, '');
if (implClass === baseClass) {
  console.error(`${input}: FAILED — base class '${baseClass}' does not end in 'Base'; cannot derive an implementation name.`);
  process.exit(1);
}

// Every signature NSwag emits for this style is a single line of the form
//   public abstract <return type> <Name>(<params>);
const SIGNATURE = /^\s*public abstract (?<returns>.+?) (?<name>\w+)\((?<params>.*)\);\s*$/gm;

const operations = [...source.matchAll(SIGNATURE)].map((m) => ({
  returns: m.groups.returns,
  name: m.groups.name,
  // Attributes such as [FromBody] belong to the base declaration; an override
  // restates only the types and names.
  params: m.groups.params.replace(/\[[^\]]+\]\s*/g, '').trim(),
}));

if (operations.length === 0) {
  console.error(`${input}: FAILED — found no abstract operations to implement.`);
  process.exit(1);
}

// `Task<ActionResult<T>>` and `Task<IActionResult>` both accept a StatusCodeResult,
// the former through ActionResult<T>'s implicit conversion. Naming the type
// argument explicitly keeps that conversion unambiguous.
const resultType = (returns) => {
  const inner = returns.match(/^System\.Threading\.Tasks\.Task<(.+)>$/)?.[1];
  if (!inner) {
    console.error(`${input}: FAILED — unsupported return type '${returns}' on an abstract operation.`);
    process.exit(1);
  }
  return inner;
};

const body = operations
  .map(
    (op) => `        /// <summary>Not implemented — this is a generated stub (AUTH-020).</summary>
        public override System.Threading.Tasks.Task<${resultType(op.returns)}> ${op.name}(${op.params})
        {
            return System.Threading.Tasks.Task.FromResult<${resultType(op.returns)}>(StatusCode(501));
        }`,
  )
  .join('\n\n');

const file = `//----------------------
// <auto-generated>
//     Generated by scripts/generate-stub-impl.mjs from ${input.replace(/\\/g, '/')}.
//     Do not edit. Run \`npm run generate\` to regenerate.
// </auto-generated>
//----------------------

namespace ${namespace}
{
    /// <summary>
    /// The routed implementation of the generated contract. Every operation
    /// returns 501 Not Implemented: the specifications are proven to generate a
    /// compiling, serving skeleton, and nothing behind them is built
    /// (ADR-0005 — bounded slice).
    /// </summary>
    [System.CodeDom.Compiler.GeneratedCode("generate-stub-impl.mjs", "1.0.0")]
    public class ${implClass} : ${baseClass}
    {
${body}
    }
}
`;

await writeFile(output, file);
console.log(`${output}: generated ${implClass} — ${operations.length} operation(s) returning 501.`);
